#include <vector>
#include <set>
#include <algorithm>
#include <iterator>

void process_data(const std::vector<int>& data) {
    // Strategy 1: Insert-Sort (Set)
    std::set<int> s(data.begin(), data.end()); // N * O(log N)

    // Strategy 2: Sequence-Sort (Vector + Sort + Unique)
    std::vector<int> v = data; // O(N) copy
    std::sort(v.begin(), v.end()); // O(N log N)
    v.erase(std::unique(v.begin(), v.end()), v.end()); // O(N)

    // Strategy 2 is often faster for large N due to cache efficiency, 
    // provided sorted access is only needed at the end.
}
